// Defensive coding pattern for NIO resource handling
public void processChannel(SocketChannel channel) {
    ByteBuffer buffer = Optional.ofNullable(readBuffer(channel))
        .orElseThrow(() -> new IllegalStateException("Buffer allocation failed"));

    // Using Objects.requireNonNull for early-fail in production
    Objects.requireNonNull(channel, "Channel must not be null during write");
    channel.write(buffer);
}
